-- USAGE_SKILL_END monitor.VW_AnalyseAccessPolicy
CREATE OR ALTER VIEW [monitor].[VW_AnalyseAccessPolicy]
AS
    SELECT
        [p].[AnalysisClass],
        [p].[ADGroupName],
        [p].[IsEnabled],
        [p].[ValidFromUtc],
        [p].[ValidToUtc],
        [p].[Priority],
        [p].[Comment]
    FROM
    (
        VALUES
        (
            CAST(NULL AS varchar(64)),
            CAST(NULL AS nvarchar(256)),
            CAST(NULL AS bit),
            CAST(NULL AS datetime2(0)),
            CAST(NULL AS datetime2(0)),
            CAST(NULL AS smallint),
            CAST(NULL AS nvarchar(1000))
        )
    ) AS [p]
    (
        [AnalysisClass],
        [ADGroupName],
        [IsEnabled],
        [ValidFromUtc],
        [ValidToUtc],
        [Priority],
        [Comment]
    )
    WHERE 1 = 0;
GO

