            + NCHAR(10)
            + N'| currentStatistics | 1 | 1 | [DatabaseName] sysname NULL, [SchemaName] sysname NULL, [ObjectName] sysname NULL, [ObjectId] int NOT NULL, [StatisticsName] sysname NULL, [StatisticsId] int NOT NULL, [IsIndexStatistics] bit NOT NULL, [IsAutoCreated] bit NULL, [IsUserCreated] bit NULL, [IsFiltered] bit NULL, [FilterDefinition] nvarchar(max) NULL, [FilterDefinitionStatus] varchar(40) NOT NULL, [NoRecompute] bit NULL, [IsIncremental] bit NULL, [HasPersistedSample] bit NULL, [LeadingColumnName] sysname NULL, [LastUpdated] datetime2(7) NULL, [Rows] bigint NULL, [RowsSampled] bigint NULL, [SamplePercent] decimal(19,6) NULL, [Steps] int NULL, [UnfilteredRows] bigint NULL, [ModificationCounter] bigint NULL, [ModificationPercent] decimal(19,6) NULL, [PersistedSamplePercent] float NULL, [CollectionStatus] varchar(40) NOT NULL |'
            + NCHAR(10)
