UNION ALL
SELECT CONVERT(sysname,N'monitor') AS [SchemaName],CONVERT(sysname,N'InternalSsisExecutionMetrics') AS [ObjectName],CONVERT(varchar(24),'INTERNAL_PROCEDURE') AS [ObjectType],CONVERT(varchar(24),'framework') AS [DatabaseRole],CONVERT(bit,1) AS [IsInternal],CONVERT(nvarchar(max),N'Die interne Prozedur nimmt ein Modell und einen Lauf-Capture entgegen, übergibt jeden Capture genau einmal an die bestehende Scope- und Pipelineanalyse und bildet deren gebundene Beobachtungen auf ein gemeinsames Kennzahlenschema für Paarve') AS [Description],CONVERT(varchar(16),'1.0.0') AS [SkillFormatVersion],CONVERT(nvarchar(max),N'---')
            + NCHAR(10)
