SELECT CONVERT(sysname,N'monitor') AS [SchemaName],CONVERT(sysname,N'USP_AgentProxyInventory') AS [ObjectName],CONVERT(varchar(24),'PROCEDURE') AS [ObjectType],CONVERT(varchar(24),'framework') AS [DatabaseRole],CONVERT(bit,0) AS [IsInternal],CONVERT(nvarchar(max),N'Inventarisiert SQL-Agent-Proxies, ihre Credentialreferenzen und ihre zugeordneten Subsysteme aus lesbaren Katalogquellen.') AS [Description],CONVERT(varchar(16),'1.0.0') AS [SkillFormatVersion],CONVERT(nvarchar(max),N'---')
