            + NCHAR(10)
            + N'| permissions | 1 | 1 | [DatabaseId] int NOT NULL, [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL, [GranteePrincipalId] int NOT NULL, [GranteeName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL, [GrantorPrincipalId] int NOT NULL, [GrantorName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL, [Class] tinyint NOT NULL, [ClassDescription] nvarchar(60) COLLATE SQL_Latin1_General_CP1_CS_AS NULL, [MajorId] int NOT NULL, [MinorId] int NOT NULL, [PermissionName] nvarchar(128) COLLATE SQL_Latin1_General_CP1_CS_AS NULL, [PermissionState] char(1) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL, [PermissionStateDescription] nvarchar(60) COLLATE SQL_Latin1_General_CP1_CS_AS NULL |'
            + NCHAR(10)
