            + NCHAR(10)
            + N'| @LanguageNames | nvarchar(max) | nein | NULL |'
            + NCHAR(10)
            + N'| @LanguageNamePattern | nvarchar(4000) | nein | NULL |'
            + NCHAR(10)
            + N'| @SampleSeconds | tinyint | nein | 0 |'
            + NCHAR(10)
