            + N'| counters | 1 | 1 | [ObjectName] nvarchar(128) NOT NULL , [CounterName] nvarchar(128) NOT NULL , [InstanceName] nvarchar(128) NOT NULL , [CounterType] int NOT NULL , [Interpretation] varchar(40) NOT NULL , [MetricValue] decimal(38,6) NULL , [MetricUnit] varchar(40) NOT NULL , [BeforeValue] bigint NULL , [AfterValue] bigint NOT NULL , [BaseBeforeValue] bigint NULL , [BaseAfterValue] bigint NULL , [DeltaValue] bigint NULL , [BaseDeltaValue] bigint NULL , [SampleSeconds] decimal(19,6) NULL , [SqlServerStartTime] datetime2(3) NULL , [FindingCode] varchar(80) NOT NULL |'
            + NCHAR(10)
            + NCHAR(10)
            + N'Bei @Hilfe=1 kommt genau ein Resultset mit SkillFormatVersion, SchemaName, ObjectName und SkillMarkdown hinzu; bestehende PRINT-Hinweise bleiben erhalten.'
