            + NCHAR(10)
            + N'Beispiel 3: DECLARE @Json nvarchar(max), @Status varchar(40), @Partial bit, @Error int, @Message nvarchar(2048), @ReturnCode int; EXEC @ReturnCode=[monitor].[USP_ServiceBrokerAnalysis] @DatabaseNames=N''[ExampleDatabase]'', @HighImpactConfirmed=1, @ResultSetArt=''NONE'', @JsonErzeugen=1, @Json=@Json OUTPUT, @StatusCodeOut=@Status OUTPUT, @IsPartialOut=@Partial OUTPUT, @ErrorNumberOut=@Error OUTPUT, @ErrorMessageOut=@Message OUTPUT, @PrintMeldungen=0; SELECT @ReturnCode AS [ReturnCode], @Status AS [StatusCode], @Partial AS [IsPartial], @Error AS [ErrorNumber], @Message AS [ErrorMessage], @Json AS [DiagnosticJson];'
            + NCHAR(10)
            + N'Beispiel 4: CREATE TABLE [#ServiceBrokerAnalysis_HelpExample] ([Seed] int NULL); BEGIN TRY EXEC [monitor].[USP_ServiceBrokerAnalysis] @DatabaseNames=N''[ExampleDatabase]'', @HighImpactConfirmed=1, @ResultSetArt=''TABLE'', @ResultTablesJson=N''{"findings":"#ServiceBrokerAnalysis_HelpExample"}'', @PrintMeldungen=0; SELECT * FROM [#ServiceBrokerAnalysis_HelpExample]; DROP TABLE IF EXISTS [#ServiceBrokerAnalysis_HelpExample]; END TRY BEGIN CATCH DROP TABLE IF EXISTS [#ServiceBrokerAnalysis_HelpExample]; THROW; END CATCH;'
