            + N'LL , [ValueHandlingStatus] varchar(40) NOT NULL , [ValueSource] varchar(40) NOT NULL , [SourceObservedAtUtc] datetime2(3) NOT NULL , [ValueCapturedAtUtc] datetime2(3) NULL , [IsCurrentExecution] bit NULL , [IsLastKnownExecution] bit NULL , [IsComplete] bit NOT NULL , [EvidenceLimit] nvarchar(1000) NULL |'
            + NCHAR(10)
