            + N'| moduleStatus | 1 | 1 | [ModuleName] sysname NOT NULL , [CapturedAtUtc] datetime2(3) NOT NULL , [StatusCode] varchar(40) NOT NULL , [IsPartial] bit NOT NULL , [SampleSeconds] tinyint NOT NULL , [ReturnedSchedulerRows] bigint NOT NULL , [ReturnedRequestRows] bigint NOT NULL , [HasMoreRequestRows] bit NOT NULL , [ErrorNumber] int NULL , [ErrorMessage] nvarchar(2048) NULL |'
            + NCHAR(10)
            + N'| summary | 1 | 1 | [CapturedAtUtc] datetime2(3) NOT NULL , [SampleStartUtc] datetime2(3) NOT NULL , [SampleEndUtc] datetime2(3) NOT NULL , [SampleSeconds] decimal(19,6) NOT NULL , [VisibleOnlineSchedulers] int NULL , [ConfiguredMaxWorkerThreads] int NULL , [EffectiveMaxWorkers] int NULL , [CurrentWorkerCount] int NULL , [AvailableWorkerCapacity] int NULL , [WorkerOccupancyPercent] decimal(9,2) NULL , [TotalWorkQueueCount] bigint NULL , [TotalRunnableTasks] bigint NULL , [MaxWorkQueuePerScheduler] bigint NULL , [MaxRunnablePerScheduler] int NULL , [ThreadpoolWaitingTaskCount] bigint NULL , [BlockingRequestCount] bigint NULL , [LongRequestCount] bigint NULL , [FailedToCreateWorkerSchedulers] int NULL , [FindingCode] varchar(80) NOT NULL , [Interpretation] nvarchar(1000) NOT NULL |'
            + NCHAR(10)
            + N'| schedulers | 1 | 1 | [SchedulerId] int NOT NULL , [ParentNodeId] int NOT NULL , [CpuId] smallint NOT NULL , [Status] nvarchar(60) NOT NULL , [SampleSeconds] decimal(19,6) NOT NULL , [CurrentTasks] int NOT NULL , [RunnableTasks] int NOT NULL , [CurrentWorkers] int NOT NULL , [ActiveWorkers] int NOT NULL , [WorkQueueCount] bigint NOT NULL , [PendingDiskIoCount] int NOT NULL , [WorkerCountFromWorkerDmv] int NULL , [RunningWorkers] int NULL , [RunnableWorkers] int NULL , [SuspendedWorkers] int NULL , [PreemptiveWorkers] int NULL , [SickWorkers] int NULL , [WorkQueueDelta] bigint NULL , [RunnableTasksDelta] int NULL , [CurrentWorkersDelta] int NULL , [ActiveWorkersDelta] int NULL , [ContextSwitchDelta] bigint NULL , [YieldDelta] bigint NULL , [CpuUsageDeltaMs] bigint NULL , [SchedulerDelayDeltaMs] bigint NULL , [CounterResetDetected] bit NOT NULL , [FailedToCreateWorker] bit NULL , [IdealWorkersLimit] int NULL , [FindingCode] varchar(80) NOT NULL , [EvidenceLimit] nvarchar(1000) NOT NULL '
            + N'|'
            + NCHAR(10)
            + N'| waits | 1 | 1 | [WaitType] nvarchar(60) NOT NULL , [WaitingTaskCount] bigint NOT NULL , [MaxWaitDurationMs] bigint NOT NULL , [BlockedTaskCount] bigint NOT NULL , [FindingCode] varchar(80) NOT NULL |'
            + NCHAR(10)
            + N'| requests | 1 | 1 | [SessionId] smallint NOT NULL , [RequestId] int NOT NULL , [SchedulerId] int NULL , [RequestStatus] nvarchar(30) NOT NULL , [Command] nvarchar(32) NOT NULL , [ElapsedMs] int NOT NULL , [CpuMs] int NOT NULL , [LogicalReads] bigint NOT NULL , [Reads] bigint NOT NULL , [Writes] bigint NOT NULL , [Dop] smallint NULL , [BlockingSessionId] smallint NULL , [WaitType] nvarchar(60) NULL , [WaitTimeMs] int NOT NULL , [ContextReason] varchar(80) NOT NULL , PRIMARY KEY([SessionId],[RequestId]) |'
            + NCHAR(10)
            + N'| sourceStatus | 1 | 1 | [SourceOrdinal] int NOT NULL PRIMARY KEY , [SourceName] sysname NOT NULL , [SourceObject] nvarchar(256) NOT NULL , [CapturedAtUtc] datetime2(3) NOT NULL , [StatusCode] varchar(40) NOT NULL , [IsPartial] bit NOT NULL , [ReturnedRowCount] bigint NOT NULL , [ErrorNumber] int NULL , [ErrorMessage] nvarchar(2048) NULL , [EvidenceLimit] nvarchar(1000) NOT NULL |'
            + NCHAR(10)
            + N'| warnings | 1 | 1 | [WarningOrdinal] int IDENTITY(1,1) NOT NULL , [SourceName] sysname NOT NULL , [StatusCode] varchar(40) NOT NULL , [ErrorNumber] int NULL , [Message] nvarchar(2048) NOT NULL |'
            + NCHAR(10)
            + NCHAR(10)
            + N'Bei @Hilfe=1 kommt genau ein Resultset mit SkillFormatVersion, SchemaName, ObjectName und SkillMarkdown hinzu; bestehende PRINT-Hinweise bleiben erhalten.'
